// ============================================================
// The Southern Cone, deeper: Scottish and Methodist beginnings in Buenos Aires, the secular laws
// of Argentina and Uruguay, Mennonite colonies in Paraguay and Uruguay, Protestant schools and
// churches in Chile, the churches under military rule, and the faith of the plains and the islands.
// Merged into the main dataset by data.js. Every event carries its sources.
// ============================================================
import { w } from "./sources.js";

function ev(era, year, figure, title, description, titleEs, descriptionEs, sources) {
  return { era, year, figure, title, description, es: { title: titleEs, description: descriptionEs }, sources };
}
const wiki = (title, slug) => w(`Wikipedia, "${title}"`, "https://en.wikipedia.org/wiki/" + (slug || title.replace(/ /g, "_")));
const wikies = (title, slug) => w(`Wikipedia (es), "${title}"`, "https://es.wikipedia.org/wiki/" + (slug || title.replace(/ /g, "_")));
const loc = (id, name, place, country, countryEs, region, regionEs, lat, lng, events, placeEs) =>
  ({ id, name, modernName: `${place}, ${country}`, region, lat, lng, significance: "minor", zone: "south",
     es: { name, modernName: `${placeEs || place}, ${countryEs}`, region: regionEs }, events });

const ALL = {
  "buenos-aires": [
    ev(4, 1829, null, "The Scots Kirk of Buenos Aires",
      "Scottish settlers who had come to the River Plate in the 1820s, led by the Rev. William Brown, built a chapel and Sunday school, and the church of St Andrew was opened in 1829. It grew into the Iglesia Presbiteriana San Andrés in the Monserrat district, whose present neo-Gothic building dates from 1896. For decades it ministered mainly in English to British residents; Spanish-language services began in 1912. Its records of baptisms, marriages and burials from 1827 are a source for the history of the early Protestant community in Argentina.",
      "La iglesia escocesa de Buenos Aires",
      "Colonos escoceses llegados al Río de la Plata en la década de 1820, con el reverendo William Brown, levantaron una capilla y una escuela dominical, y la iglesia de San Andrés se inauguró en 1829. Se convirtió en la Iglesia Presbiteriana San Andrés del barrio de Monserrat, cuyo templo neogótico actual data de 1896. Durante décadas atendió sobre todo en inglés a los residentes británicos; los cultos en español comenzaron en 1912. Sus registros de bautismos, matrimonios y entierros desde 1827 son una fuente para la historia de la comunidad protestante temprana en Argentina.",
      [wiki("Iglesia Presbiteriana San Andrés (Centro)", "Iglesia_Presbiteriana_San_Andr%C3%A9s_(Centro)"),
       w("Iglesia Presbiteriana San Andrés, Revista San Andrés 2004: 175 años de testimonio, 1829–2004", "https://old.ipsa.org.ar/revista,%20registro%20historico/RSA%202004%20-%20Completo/RSA%20-%202004%20-%201.pdf"),
       w("Argentine-British records, \"Baptisms, marriages and burials at St Andrew's Church, Buenos Aires, 1827–1915\"", "https://www.argbrit.org/SanAintro/entry.html")]),
    ev(4, 1836, "John Dempster", "John Dempster and the First Methodists in Buenos Aires",
      "Argentine Methodists date their church from 1836, when John Dempster, sent by the Methodist Episcopal Church of New York, began work in Buenos Aires. Accounts differ on the exact arrival and on the opening of the first chapel on Calle Cangallo, given as early 1843 in one source; Dempster was followed by William P. Norris in 1842 and Dallas D. Lore in 1847. Preaching in Spanish was restricted until the late 1860s. The present neo-Gothic Primera Iglesia Evangélica Metodista was completed in 1874 and is listed as a heritage site by the city.",
      "John Dempster y los primeros metodistas de Buenos Aires",
      "Los metodistas argentinos fechan su iglesia en 1836, cuando John Dempster, enviado por la Iglesia Metodista Episcopal de Nueva York, comenzó su obra en Buenos Aires. Los relatos difieren sobre la fecha exacta de llegada y sobre la apertura de la primera capilla en la calle Cangallo, que una fuente sitúa a comienzos de 1843; a Dempster lo siguieron William P. Norris en 1842 y Dallas D. Lore en 1847. La predicación en español estuvo restringida hasta fines de la década de 1860. La actual Primera Iglesia Evangélica Metodista, neogótica, se completó en 1874 y la Ciudad la reconoce como sitio de interés cultural.",
      [wiki("Primera Iglesia Evangélica Metodista Buenos Aires", "Primera_Iglesia_Evang%C3%A9lica_Metodista_Buenos_Aires"),
       w("United Methodist Church (umc.org), \"First Methodist mission in Argentina\"", "https://www.umc.org/content/first-methodist-mission-in-argentina"),
       w("Gobierno de la Ciudad de Buenos Aires, Sitios de Interés Cultural: Primera Iglesia Metodista", "https://buenosaires.gob.ar/areas/cultura/cpphc/sitios/detalle.php?id=49")]),
    ev(5, 1884, null, "Law 1420: Common, Secular Schooling",
      "On 8 July 1884, under President Julio A. Roca, Argentina sanctioned Law 1420 on free, compulsory common education, after fierce debate in the press and the National Congress. Article 8 placed religious teaching outside the obligatory school hours, to be given by ministers of each faith, and Catholic leaders such as Pedro Goyena and José Manuel Estrada resisted it. Supporters argued that the state should form citizens, not Catholic believers. Because it imposed no religious teaching in school hours, the public school could receive children of every creed, and the law became a cornerstone of Argentine secular tradition.",
      "Ley 1420: escuela común y laica",
      "El 8 de julio de 1884, bajo la presidencia de Julio A. Roca, Argentina sancionó la Ley 1420 de educación común, gratuita y obligatoria, tras un fuerte debate en la prensa y el Congreso Nacional. El artículo 8 ubicó la enseñanza religiosa fuera del horario escolar obligatorio, a cargo de los ministros de cada culto, y dirigentes católicos como Pedro Goyena y José Manuel Estrada se opusieron. Sus defensores sostenían que el Estado debía formar ciudadanos, no creyentes católicos. Al no imponer enseñanza religiosa en el horario escolar, la escuela pública pudo recibir a niños de todos los credos, y la ley se volvió piedra angular de la tradición laica argentina.",
      [w("Ministerio de Educación de la Nación, Biblioteca Nacional de Maestros: Ley de Educación Común 1420", "https://bnm.me.gov.ar/proyectos/medar/historia_investigacion/1880_1910/politicas_educativas/ley_1420.php"),
       w("Anales de la Educación Común (Dirección General de Cultura y Educación, Buenos Aires), article on Law 1420 and religious teaching", "https://cendie.abc.gob.ar/revistas/index.php/revistaanales/article/download/2206/3456/3378")]),
    ev(5, 1888, null, "Civil Marriage Law Takes Registration from the Church",
      "Law 2393 on civil marriage, passed on 12 November 1888, ended the Catholic Church's role as sole registrar of marriages in Argentina. Before it, priests celebrated and recorded marriages; afterwards, to have civil effect a marriage had to be celebrated before a public official. The measure, debated hard by liberals and Catholics, belonged to the secularising laws of the 1880s alongside the school law of 1884. It was one of the laws that built Argentina's secular legal framework.",
      "La ley de matrimonio civil quita el registro a la Iglesia",
      "La Ley 2393 de matrimonio civil, sancionada el 12 de noviembre de 1888, puso fin al papel de la Iglesia católica como único registro de matrimonios en Argentina. Antes, los sacerdotes celebraban y asentaban los matrimonios; después, para tener efectos civiles el matrimonio debía celebrarse ante un oficial público. La medida, muy discutida entre liberales y católicos, formó parte de las leyes secularizadoras de los años ochenta, junto con la ley escolar de 1884. Fue una de las leyes que construyeron el marco jurídico laico de Argentina.",
      [w("educ.ar (Ministerio de Educación), \"Ley N.º 2393 de Matrimonio Civil\"", "https://www.educ.ar/recursos/128706/ley-n-2393-de-matrimonio-civil"),
       w("María C. I. Diez, \"La génesis del matrimonio civil\", Prudentia Iuris (Universidad Católica Argentina)", "https://repositorio.uca.edu.ar/bitstream/123456789/2964/1/genesis-matrimonio-civil-maria-diez.pdf")]),
    ev(5, 1934, null, "The International Eucharistic Congress of Buenos Aires",
      "From 9 to 14 October 1934 Buenos Aires hosted the 32nd International Eucharistic Congress, presided over by Cardinal Eugenio Pacelli, the future Pius XII, as personal legate of Pius XI. Chronologies list it as the first such congress in South America, under the motto of the social kingship of Christ through the Eucharist. Contemporary press spoke of a million people welcoming the legate, and historians read it as the high point of a rapprochement between the Church and the government of General Agustín P. Justo, a display of Catholic public presence in a country that had secularised its schools and marriage.",
      "El Congreso Eucarístico Internacional de Buenos Aires",
      "Del 9 al 14 de octubre de 1934 Buenos Aires fue sede del XXXII Congreso Eucarístico Internacional, presidido por el cardenal Eugenio Pacelli, futuro Pío XII, como legado personal de Pío XI. Las cronologías lo señalan como el primero de su tipo en Sudamérica, bajo el lema de la realeza social de Cristo por la Eucaristía. La prensa de la época habló de un millón de personas recibiendo al legado, y los historiadores lo leen como el punto culminante de un acercamiento entre la Iglesia y el gobierno del general Agustín P. Justo, una demostración de presencia pública católica en un país que había laicizado la escuela y el matrimonio.",
      [wikies("Congreso Eucarístico Internacional de 1934", "Congreso_Eucar%C3%ADstico_Internacional_de_1934"),
       w("La Nación, \"Congreso Eucarístico Internacional de 1934\"", "https://lanacion.com.ar/opinion/congreso-eucaristico-internacional-de-1934-nid19122024"),
       w("Papers Past (National Library of New Zealand), \"Eucharistic Congress at Buenos Aires\", Hawera and Normanby Star, 15 Oct 1934", "https://paperspast.natlib.govt.nz/newspapers/HC19341015.2.43")]),
    ev(6, 1955, null, "The Burning of the Churches",
      "In 1954–55 the government of Juan Domingo Perón and the Catholic Church, once allies, fell into open conflict. After a large Corpus Christi procession on 11 June 1955 turned into an anti-government demonstration, naval aircraft bombed the centre of Buenos Aires on 16 June. That night crowds set fire to churches, among them the Curia and several historic city churches; accounts differ on how many were burned, and whether Perón ordered the attacks is disputed. Three months later the Revolución Libertadora overthrew him. The episode left a deep mark on relations between the Church, Peronism and the state.",
      "La quema de las iglesias",
      "En 1954–55 el gobierno de Juan Domingo Perón y la Iglesia católica, antes aliados, cayeron en un conflicto abierto. Tras una gran procesión de Corpus Christi el 11 de junio de 1955, convertida en manifestación opositora, aviones navales bombardearon el centro de Buenos Aires el 16 de junio. Esa noche multitudes incendiaron templos, entre ellos la Curia y varias iglesias históricas de la ciudad; los relatos difieren sobre cuántos ardieron, y es discutido si Perón ordenó los ataques. Tres meses después la Revolución Libertadora lo derrocó. El episodio dejó una marca profunda en la relación entre la Iglesia, el peronismo y el Estado.",
      [w("La Nación, \"La quema de iglesias: furia contra los templos\"", "https://www.lanacion.com.ar/opinion/la-quema-de-iglesias-furia-contra-los-templos-nid712038/"),
       wiki("Bombing of Plaza de Mayo"),
       w("El Litoral, \"La masacre del 16 de junio de 1955\"", "https://www.ellitoral.com/opinion/masacre-16-junio-1955_0_eI1anbnM0w.html")]),
    ev(6, 1976, null, "The Ecumenical Movement for Human Rights",
      "During the last military dictatorship the Movimiento Ecuménico por los Derechos Humanos (MEDH) was born in 1976 as a non-governmental body bringing together members of the Catholic Church, several Protestant churches and the Lutheran Church. Its aim was to mobilise the churches to demand that the state meet its human-rights obligations at a time when disappearances and kidnappings were widespread. It operated in the same field as the Asamblea Permanente por los Derechos Humanos, and remains an example of Protestant and Catholic cooperation in defence of life under repression.",
      "El Movimiento Ecuménico por los Derechos Humanos",
      "Durante la última dictadura militar nació en 1976 el Movimiento Ecuménico por los Derechos Humanos (MEDH), organización no gubernamental que reunió a miembros de la Iglesia católica, de varias iglesias protestantes y de la Iglesia Luterana. Su propósito era movilizar a las iglesias para exigir que el Estado cumpliera sus obligaciones en derechos humanos, en un tiempo de desapariciones y secuestros generalizados. Actuó en el mismo campo que la Asamblea Permanente por los Derechos Humanos, y sigue siendo un ejemplo de cooperación entre protestantes y católicos en defensa de la vida bajo la represión.",
      [wikies("Movimiento Ecuménico por los Derechos Humanos", "Movimiento_Ecum%C3%A9nico_por_los_Derechos_Humanos"),
       w("Comisión Provincial por la Memoria (Buenos Aires), dossier on human-rights organisations", "https://www.comisionporlamemoria.org/archivos/educacion/organismos/dossier5.pdf")]),
    ev(6, 1994, null, "The Catholic Requirement for the Presidency Is Dropped",
      "The constitutional reform of 1994 removed the requirement, in force since 1853, that the president and vice-president of Argentina belong to the Catholic communion, and also dropped the oath formula tied to it. Commentators note that no religious qualification now conditions access to the highest offices. The reform did not touch Article 2, which says the federal government 'sustains the Roman Catholic Apostolic faith', so the state still treats Catholicism differently from other creeds. Commentators observe that Article 2 reproduces the state's differentiated treatment of religious denominations.",
      "Se elimina el requisito católico para la presidencia",
      "La reforma constitucional de 1994 eliminó el requisito, vigente desde 1853, de que el presidente y el vicepresidente de Argentina pertenecieran a la comunión católica, y suprimió también la fórmula de juramento vinculada a él. Los comentaristas señalan que hoy ningún requisito religioso condiciona el acceso a los más altos cargos. La reforma no tocó el artículo 2, según el cual el gobierno federal sostiene el culto católico apostólico romano, de modo que el Estado sigue dando un trato distinto al catolicismo frente a otros credos. Los comentaristas observan que el artículo 2 reproduce el trato diferenciado del Estado hacia las confesiones religiosas.",
      [w("Honorable Cámara de Diputados de la Nación, Constitución Nacional, text of 1994 (PDF)", "https://www3.hcdn.gob.ar/reforma_constitucional/documentos/Texto_Constitucion_Nacional_1994.pdf"),
       w("Universidad Católica Argentina, \"Inspiraciones constitucionales y factor religioso\"", "https://repositorio.uca.edu.ar/bitstream/123456789/5670/1/inspiraciones-constitucionales-factor-religioso.pdf")]),
  ],
  "almagro": [
    ev(6, 1982, "Héctor Giménez", "Héctor Giménez and Ondas de Amor y Paz",
      "Héctor Aníbal Giménez, who said he had been delinquent and drug-dependent in his youth, began pastoral work in 1982 from a rehabilitation centre he called Ondas de Amor y Paz, and preached in the open air on Calle Corrientes near the Obelisco. The ministry grew into one of Argentina's best-known media-oriented evangelical churches, filling Luna Park and football stadiums and holding its services in a large temple in the Almagro district of Buenos Aires, a gathering place for people from the arts and politics. Giménez later faced legal and public controversies.",
      "Héctor Giménez y Ondas de Amor y Paz",
      "Héctor Aníbal Giménez, que contó haber sido delincuente y adicto en su juventud, comenzó su obra pastoral en 1982 desde un centro de rehabilitación llamado Ondas de Amor y Paz, y predicó al aire libre en la calle Corrientes, cerca del Obelisco. El ministerio creció hasta ser una de las iglesias evangélicas mediáticas más conocidas de Argentina, llenó el Luna Park y estadios de fútbol, y celebró sus cultos en un gran templo del barrio de Almagro, en Buenos Aires, lugar de encuentro de figuras del arte y la política. Más tarde Giménez enfrentó controversias judiciales y públicas.",
      [wikies("Héctor Aníbal Giménez", "H%C3%A9ctor_An%C3%ADbal_Gim%C3%A9nez"),
       w("La Nación, \"La curiosa historia del exitoso pastor mediático\"", "https://www.lanacion.com.ar/economia/la-curiosa-historia-del-exitoso-pastor-mediatico-nid2362758"),
       w("Infobae, \"La nueva vida del pastor Giménez\" (2018)", "https://www.infobae.com/sociedad/2018/10/28/la-nueva-vida-del-pastor-gimenez-de-lider-espiritual-de-los-famosos-al-perfil-bajo-despues-del-divorcio-y-un-escandalo-millonario/")]),
  ],
  "santa-fe-ar": [
    ev(4, 1853, null, "Article 14: Freedom of Worship in the Constitution",
      "The Constitution approved at Santa Fe in 1853 guaranteed foreigners and citizens the right 'to profess freely their worship' (Article 14). Juan Bautista Alberdi, in his Bases, had argued that excluding non-Catholics, above all Protestants, meant excluding the settlers the continent most needed; scholars note the clause aimed to attract northern European immigrants, imagined as Protestant. The constituent debate of 24 April 1853 pitted its defenders against Catholic opponents. Yet Article 2 kept the federal government's support of the Catholic faith, a combination of religious liberty and legal inequality that shaped Protestant life for generations.",
      "Artículo 14: la libertad de cultos en la Constitución",
      "La Constitución aprobada en Santa Fe en 1853 garantizó a extranjeros y ciudadanos el derecho de 'profesar libremente su culto' (artículo 14). Juan Bautista Alberdi, en sus Bases, había sostenido que excluir a los no católicos, sobre todo a los protestantes, equivalía a excluir a los pobladores que más necesitaba el continente; los estudiosos señalan que la cláusula buscaba atraer inmigrantes del norte de Europa, imaginados protestantes. El debate constituyente del 24 de abril de 1853 enfrentó a sus defensores con opositores católicos. Pero el artículo 2 mantuvo el sostén federal al culto católico, una combinación de libertad religiosa y desigualdad jurídica que marcó por generaciones la vida de los protestantes.",
      [w("Presidencia de la Nación, on Alberdi's Bases and the 1853 Constitution", "https://www.argentina.gob.ar/node/138260"),
       w("Historia Mexicana (El Colegio de México), article on religious liberty and Church–state regimes in the Río de la Plata", "https://www.scielo.org.mx/pdf/hm/v74n4/2448-6531-hm-74-04-1703.pdf"),
       wikies("Constitución de la Nación Argentina", "Constituci%C3%B3n_de_la_Naci%C3%B3n_Argentina")]),
  ],
  "parana": [
    ev(5, 1870, "George A. Stearns", "Sarmiento's Normal School and the North American Teachers",
      "President Domingo F. Sarmiento founded the Escuela Normal de Paraná in 1870, the first normal school of Argentina, which opened its classes in August 1871. Its first director, George A. Stearns, was hired from the United States; one source notes he was the son and grandson of Protestant pastors. Between 1869 and 1898 some sixty North American teachers, most of them women, came to staff the normal schools of the interior. Their arrival brought a Protestant-educated, secular pedagogy into a country still dominated by Catholic schooling and helped shape the public school system.",
      "La Escuela Normal de Sarmiento y las maestras norteamericanas",
      "El presidente Domingo F. Sarmiento fundó en 1870 la Escuela Normal de Paraná, la primera escuela normal de Argentina, que abrió sus clases en agosto de 1871. Su primer director, George A. Stearns, fue contratado en Estados Unidos; una fuente señala que era hijo y nieto de pastores protestantes. Entre 1869 y 1898 llegaron unos sesenta docentes norteamericanos, en su mayoría mujeres, para dotar de personal a las escuelas normales del interior. Su venida trajo una pedagogía laica formada en el ámbito protestante a un país dominado por la enseñanza católica y contribuyó a dar forma al sistema de escuela pública.",
      [wikies("Escuela Normal Superior José María Torres", "Escuela_Normal_Superior_Jos%C3%A9_Mar%C3%ADa_Torres"),
       w("Billiken, \"¿Cuál fue la primera escuela normal de Argentina?\"", "https://billiken.lat/interesante/la-primera-escuela-normal-de-argentina-estuvo-en-parana/"),
       w("Editorial UADER, Escuela Normal de Paraná (Colección Eureka), chapter 3 (PDF)", "https://editorial.uader.edu.ar/sites/default/files/imagenes-sitio/colecciones/eureka/escuela-normal-de-parana/escuela-normal-de-parana-cap-03.pdf")]),
  ],
  "libertador-san-martin": [
    ev(5, 1898, "Frank H. Westphal", "The Adventist School of the River Plate",
      "In 1898, at a meeting in Crespo, Entre Ríos, Seventh-day Adventists under Pastor Frank H. Westphal agreed to create a school at Camarero, later Libertador General San Martín. The Colegio Camarero opened its doors in 1900, became the Colegio Adventista del Plata, and was joined by a sanatorium in 1908. Founded to train workers and educate the children of the German-speaking Adventist colonies, the school grew into the Universidad Adventista del Plata, provisionally authorised in 1990 and fully recognised in 2002. It remains a main centre of Adventist education in the Southern Cone.",
      "El colegio adventista del Plata",
      "En 1898, en una reunión en Crespo, Entre Ríos, los adventistas del séptimo día, bajo el pastor Frank H. Westphal, acordaron crear una escuela en Camarero, hoy Libertador General San Martín. El Colegio Camarero abrió sus puertas en 1900, pasó a llamarse Colegio Adventista del Plata y se le sumó un sanatorio en 1908. Fundado para formar obreros y educar a los hijos de las colonias adventistas de habla alemana, el colegio llegó a ser la Universidad Adventista del Plata, autorizada provisoriamente en 1990 y reconocida plenamente en 2002. Sigue siendo un centro principal de la educación adventista en el Cono Sur.",
      [wiki("Adventist University of the Plata"),
       w("Universidad Adventista del Plata, Revista Enfoques, article on the founding of the college", "https://publicaciones.uap.edu.ar/index.php/revistaenfoques/article/view/524/498"),
       wikies("Universidad Adventista del Plata", "Universidad_Adventista_del_Plata")]),
  ],
  "tandil": [
    ev(5, 1877, null, "The Danish Lutheran Church of Tandil",
      "Danish immigrants began to settle in the Tandil district of Buenos Aires province around the middle of the nineteenth century, with Juan Fugl settled there by 1847 and a larger first group dated to 1860 by the historian María Bjerg. In 1877 they inaugurated their Lutheran church in Tandil, said to have been built before the town's Catholic church. Together with schools and newspapers, the Danish Evangelical Lutheran Church of Argentina helped the community, some 18,000 people between 1857 and 1930, keep its language and religious identity across the 'Danish triangle' of Tandil, Necochea and Tres Arroyos.",
      "La iglesia luterana danesa de Tandil",
      "Inmigrantes daneses comenzaron a asentarse en el partido de Tandil, provincia de Buenos Aires, hacia mediados del siglo XIX: Juan Fugl se instaló allí hacia 1847 y la historiadora María Bjerg fecha en 1860 un primer grupo numeroso. En 1877 inauguraron su iglesia luterana de Tandil, que se dice fue anterior a la católica del pueblo. Junto con escuelas y periódicos, la Iglesia Evangélica Luterana Danesa de la Argentina ayudó a la comunidad, de unas 18.000 personas entre 1857 y 1930, a conservar su lengua y su identidad religiosa en el 'triángulo danés' de Tandil, Necochea y Tres Arroyos.",
      [wiki("Danish Argentines"),
       w("Revista de Indias (CSIC), article on the Danish Evangelical Lutheran Church of Argentina and immigrant identity", "https://revistadeindias.revistas.csic.es/index.php/revistadeindias/article/download/820/889/1310"),
       w("La Nación, \"Margarita II se despidió de Argentina con afecto a la colectividad\"", "https://www.lanacion.com.ar/sociedad/margarita-ii-se-despidio-argentina-afecto-colectividad-nid2230542")]),
  ],
  "ushuaia": [
    ev(5, 1871, "Thomas Bridges", "Thomas Bridges and the Mission at Ushuaia",
      "In 1871 the Anglican missionary Thomas Bridges, raised in the Falkland Islands and fluent in the Yahgan (Yámana) language, took charge of the South American Missionary Society's station at Ushuaia with his young family. The mission grew into a 'Christian village' with houses, a school, chapel and workshops, today the Barrio La Misión. Bridges compiled a Yahgan grammar and dictionary of some 30,000 words, completed about 1879. He resigned in 1886 and founded the Estancia Harberton, as the Argentine state and Salesian missionaries arrived and the Yahgan population fell under the pressure of settlement and disease.",
      "Thomas Bridges y la misión de Ushuaia",
      "En 1871 el misionero anglicano Thomas Bridges, criado en las islas Malvinas y conocedor de la lengua yagán (yámana), se hizo cargo con su joven familia de la estación de la Sociedad Misionera Sudamericana en Ushuaia. La misión creció hasta ser una 'villa cristiana' con viviendas, escuela, capilla y talleres, hoy el barrio La Misión. Bridges compiló una gramática y un diccionario yagán de unas 30.000 palabras, completados hacia 1879. Renunció en 1886 y fundó la Estancia Harberton, cuando llegaban el Estado argentino y los misioneros salesianos y la población yagán caía bajo la presión del asentamiento y las enfermedades.",
      [wiki("Thomas Bridges (missionary)", "Thomas_Bridges_(missionary)"),
       w("Falklands Biographies, \"Bridges, Thomas\"", "https://www.falklandsbiographies.org/biographies/bridges_thomas"),
       wiki("Estancia Harberton")]),
  ],
  "la-rioja": [
    ev(6, 1976, "Enrique Angelelli", "The Murder of Bishop Angelelli",
      "On 4 August 1976 Enrique Angelelli, Catholic bishop of La Rioja and a council father at Vatican II, died when his vehicle was forced off Route 38 at Punta de los Llanos as he returned from Chamical, where he had celebrated Mass for two priests killed days earlier. The crash was presented as an accident, but in 2014 a court ruled it a homicide and sentenced Luciano B. Menéndez and Luis F. Estrella. Angelelli's martyrdom was recognised on 8 June 2018, and he was beatified at La Rioja on 27 April 2019 with priests Carlos Murias and Gabriel Longueville and layman Wenceslao Pedernera.",
      "El asesinato del obispo Angelelli",
      "El 4 de agosto de 1976 murió Enrique Angelelli, obispo católico de La Rioja y padre conciliar en el Vaticano II, cuando su vehículo fue embestido en la ruta 38, en Punta de los Llanos, al volver de Chamical, donde había celebrado una misa por dos sacerdotes asesinados días antes. El hecho se presentó como un accidente, pero en 2014 la justicia lo calificó de homicidio y condenó a Luciano B. Menéndez y Luis F. Estrella. El martirio de Angelelli fue reconocido el 8 de junio de 2018 y fue beatificado en La Rioja el 27 de abril de 2019 junto con los sacerdotes Carlos Murias y Gabriel Longueville y el laico Wenceslao Pedernera.",
      [w("Vatican News, \"Argentina: 50 años del martirio de monseñor Angelelli\"", "https://www.vaticannews.va/es/iglesia/news/2026-08/argentina-50-anos-del-martirio-de-monsenor-angelelli.html"),
       wikies("Enrique Angelelli", "Enrique_Angelelli"),
       w("Canal 26, \"Beatificaron al obispo Angelelli, asesinado por la dictadura militar en 1976\"", "https://www.canal26.com/general/2019/04/27/beatificaron-al-obispo-angelelli-asesinado-por-la-dictadura-militar-en-1976/")]),
  ],
  "cordoba": [
    ev(2, 1613, null, "The University of Córdoba",
      "The Universidad Nacional de Córdoba traces its foundation to 19 June 1613, making it the oldest university in Argentina and one of the first in Latin America; it began in the Jesuit college of Córdoba. Its Jesuit block, the Manzana de las Luces, with the church and college, was the centre of learning of the colonial River Plate until the expulsion of the Society in 1767. The institution is today public, free and secular, a long road from its religious origins.",
      "La Universidad de Córdoba",
      "La Universidad Nacional de Córdoba remonta su fundación al 19 de junio de 1613, lo que la hace la universidad más antigua de Argentina y una de las primeras de América Latina; nació en el colegio jesuita de Córdoba. Su manzana jesuítica, con iglesia y colegio, fue el centro del saber del Río de la Plata colonial hasta la expulsión de la Compañía en 1767. Hoy la institución es pública, gratuita y laica, un largo camino desde sus orígenes religiosos.",
      [wikies("Universidad Nacional de Córdoba", "Universidad_Nacional_de_C%C3%B3rdoba"),
       w("Universidad Nacional de Córdoba, \"Manzana Jesuítica\"", "http://www.unc.edu.ar/institucional/manzana-jesuitica/manzanadelasluces/manzana"),
       wiki("Jesuit Block and Estancias of Córdoba", "Jesuit_Block_and_Estancias_of_C%C3%B3rdoba")]),
  ],
  "crespo": [
    ev(5, 1878, null, "The Volga German Villages of Entre Ríos",
      "On 21 July 1878 the first five Volga German villages of Entre Ríos province were founded, among them Valle María, San Francisco, Spatzenkutter and Salto; a sixth followed a year later. The colonists, descendants of Germans who had settled on the Volga in Russia, organised their villages by confession: most were Catholic, while a few, like the village named Protestante, were Lutheran or Evangelical. Of fifteen villages that survive, twelve are of Catholic origin and three Protestant. In Crespo, Protestant churches remain the centre of community life, and in 1898 Adventists meeting at Crespo planned their school.",
      "Las aldeas alemanas del Volga en Entre Ríos",
      "El 21 de julio de 1878 se fundaron las primeras cinco aldeas de alemanes del Volga de la provincia de Entre Ríos, entre ellas Valle María, San Francisco, Spatzenkutter y Salto; una sexta siguió un año después. Los colonos, descendientes de alemanes asentados en el Volga ruso, organizaron sus aldeas por confesión: la mayoría eran católicas, y unas pocas, como la llamada Protestante, luteranas o evangélicas. De las quince aldeas que perduran, doce son de origen católico y tres protestantes. En Crespo, las iglesias protestantes siguen siendo el centro de la vida comunitaria, y en 1898 los adventistas reunidos en Crespo planearon su escuela.",
      [w("Volga German Institute, \"Valle María, Departamento Diamante, Entre Ríos Province\"", "https://volgagermaninstitute.org/immigration/ar/e/valle-mar%C3%ADa-departamento-diamente-entre-r%C3%ADos-province"),
       w("El Observador (Uruguay), \"Los alemanes del Volga en Argentina: el largo peregrinar\"", "https://www.elobservador.com.uy/argentina/sociedad/los-alemanes-del-volga-argentina-el-largo-peregrinar-las-estepas-europeas-las-pampas-criollas-n6009381"),
       w("Volga Germans in Argentina (volgagermans.org), Entre Ríos", "https://www.volgagermans.org/history/immigration/argentina/entre-rios")]),
  ],
  "santiago": [
    ev(4, 1821, "James (Diego) Thomson", "Diego Thomson Opens Lancasterian Schools in Chile",
      "On 17 July 1821 the Scottish Baptist James 'Diego' Thomson arrived in Chile, contracted by the government of Bernardo O'Higgins, reportedly at 1,200 pesos a year, to introduce the Lancasterian system of mutual instruction. He was also an agent of the British and Foreign Bible Society and used the Scriptures as reading texts. He founded two schools in Santiago and one in Valparaíso, but some of the educated élite viewed his purposes with suspicion. In 1822 he left for Peru. His work marks an early link between Protestant educators and the new republics' schools.",
      "Diego Thomson abre escuelas lancasterianas en Chile",
      "El 17 de julio de 1821 llegó a Chile el bautista escocés James 'Diego' Thomson, contratado por el gobierno de Bernardo O'Higgins, según se dice a 1.200 pesos anuales, para introducir el sistema lancasteriano de enseñanza mutua. Era también agente de la Sociedad Bíblica Británica y Extranjera y usaba las Escrituras como libros de lectura. Fundó dos escuelas en Santiago y una en Valparaíso, aunque parte de la élite ilustrada miró con recelo sus propósitos. En 1822 partió al Perú. Su obra señala un vínculo temprano entre educadores protestantes y las escuelas de las nuevas repúblicas.",
      [wiki("James Thomson (pastor)", "James_Thomson_(pastor)"),
       wikies("James Thompson", "James_Thompson"),
       w("Memoria Chilena, \"Historia del pueblo de Dios en Chile\" (PDF)", "https://www.memoriachilena.gob.cl/archivos2/pdfs/MC0040213.pdf")]),
    ev(4, 1868, "David Trumbull", "The Presbyterian Church of Chile",
      "The Iglesia Presbiteriana de Chile dates its founding to 7 June 1868 in Santiago, where the work of the American missionary David Trumbull and the United Presbyterian Church of the USA produced a Spanish-speaking congregation; some call it the first Chilean Protestant church. The first presbytery was organised on 13 June 1883, and the church became independent of the American body in January 1964. Other timelines place beginnings earlier, such as a service in 1847 or a church in 1855, so the founding date is a matter of how the origins are defined.",
      "La Iglesia Presbiteriana de Chile",
      "La Iglesia Presbiteriana de Chile fecha su fundación el 7 de junio de 1868 en Santiago, donde la obra del misionero estadounidense David Trumbull y de la Iglesia Presbiteriana Unida de EE. UU. dio origen a una congregación de habla hispana; algunos la consideran la primera iglesia protestante chilena. El primer presbiterio se organizó el 13 de junio de 1883, y la iglesia se hizo independiente de la entidad norteamericana en enero de 1964. Otras cronologías sitúan los comienzos antes, como un culto en 1847 o una iglesia en 1855, de modo que la fecha de fundación depende de cómo se definan los orígenes.",
      [wiki("Presbyterian Church in Chile"),
       wikies("Iglesia presbiteriana de Chile", "Iglesia_presbiteriana_de_Chile"),
       w("Memoria Chilena, \"Las iglesias evangélicas en Chile (1819–2002)\"", "https://www.memoriachilena.gob.cl/602/w3-article-712.html")]),
    ev(5, 1880, "Ira H. La Fetra", "Santiago College, a Methodist School for Girls",
      "Santiago College was founded in 1880 by the American Methodist missionary Ira H. La Fetra and his wife as a boarding school for girls, beginning in a downtown house on Calle Vergara. It later moved to the Los Leones campus in Providencia, built in 1930, and became co-educational in 1972. Chile's Memoria Chilena notes that among the private girls' schools of the time, which were all Catholic, it was the exception, being Methodist and founded by North Americans. The school is an example of the Protestant mission schools that offered Chileans an alternative to the religious education of the day.",
      "Santiago College, escuela metodista para niñas",
      "Santiago College fue fundado en 1880 por el misionero metodista estadounidense Ira H. La Fetra y su esposa como internado para niñas, y comenzó en una casa del centro, en la calle Vergara. Más tarde se trasladó al campus de Los Leones, en Providencia, construido en 1930, y pasó a ser mixto en 1972. Memoria Chilena señala que, entre los colegios particulares femeninos de la época, todos católicos, era la excepción, por ser metodista y fundado por norteamericanos. El colegio es un ejemplo de las escuelas misioneras protestantes que ofrecieron a los chilenos una alternativa a la educación religiosa de entonces.",
      [wiki("Santiago College"),
       w("Memoria Chilena, \"Liceos particulares femeninos\"", "https://www.memoriachilena.gob.cl/602/w3-article-95573.html")]),
    ev(5, 1944, "Alberto Hurtado", "Padre Hurtado Founds the Hogar de Cristo",
      "In 1944 the Chilean Jesuit Alberto Hurtado, a lawyer and priest, launched a campaign in the press, mainly in El Mercurio, that led to the founding of the Hogar de Cristo to shelter homeless children and the poor; its main headquarters opened in December 1944 on Calle Bernal del Mercado in Estación Central. The shelters spread through Chile. Hurtado died in 1952, was beatified by John Paul II on 16 October 1994 and canonised by Benedict XVI on 23 October 2005, Chile's second saint. The foundation continues its work today.",
      "El Padre Hurtado funda el Hogar de Cristo",
      "En 1944 el jesuita chileno Alberto Hurtado, abogado y sacerdote, lanzó una campaña en la prensa, sobre todo en El Mercurio, que condujo a la fundación del Hogar de Cristo para acoger a niños y personas pobres sin techo; su sede principal abrió en diciembre de 1944 en la calle Bernal del Mercado, en Estación Central. Los hogares se extendieron por Chile. Hurtado murió en 1952, fue beatificado por Juan Pablo II el 16 de octubre de 1994 y canonizado por Benedicto XVI el 23 de octubre de 2005, el segundo santo de Chile. La fundación continúa hoy su labor.",
      [wiki("Alberto Hurtado"),
       w("Teología y Vida (Pontificia Universidad Católica de Chile), article on the founding of the Hogar de Cristo", "https://www.redalyc.org/pdf/322/32214689014.pdf"),
       w("ACI Prensa, \"Hoy celebramos a San Alberto Hurtado, fundador de El Hogar de Cristo\"", "https://www.aciprensa.com/noticias/hoy-celebramos-a-san-alberto-hurtado-fundador-de-el-hogar-de-cristo-43606")]),
    ev(6, 1987, null, "John Paul II in Chile",
      "Pope John Paul II visited Chile in April 1987 as part of a thirteen-day journey through Uruguay, Chile and Argentina that included 63 speeches and some 30,600 kilometres of travel. On 2 April he met about 45,000 young people in the Estadio Nacional in Santiago. The visit took place under the military regime of General Pinochet, and slogans with political content were heard alongside the religious fervour of the crowd. The Vatican published his speeches from the arrival in Santiago on 1 April.",
      "Juan Pablo II en Chile",
      "El papa Juan Pablo II visitó Chile en abril de 1987 en un viaje de trece días por Uruguay, Chile y Argentina, con 63 discursos y unos 30.600 kilómetros recorridos. El 2 de abril se reunió con unos 45.000 jóvenes en el Estadio Nacional de Santiago. La visita se realizó bajo el régimen militar del general Pinochet, y entre el fervor religioso de la multitud se escucharon consignas de contenido político. El Vaticano publicó sus discursos desde la llegada a Santiago el 1 de abril.",
      [w("Vatican, Pope John Paul II, arrival ceremony in Chile (1 April 1987)", "https://www.vatican.va/content/john-paul-ii/es/speeches/1987/april/documents/hf_jp-ii_spe_19870401_arrivo-cile.html"),
       w("Canal 13 (Chile), \"Hace 39 años: el día que Juan Pablo II emocionó a 45 mil jóvenes en el Estadio Nacional\"", "https://www.13.cl/rec/articulos/hace-39-anos-el-dia-que-juan-pablo-ii-emociono-a-45-mil-jovenes-en-el-estadio"),
       w("Revista de Marina (Armada de Chile), article on the 1987 papal journey (PDF)", "https://revistamarina.cl/revistas/2014/3/fierro.pdf")]),
    ev(6, 2001, "Neftalí Aravena", "The First Evangelical Chaplain of La Moneda",
      "On 13 December 2001 President Ricardo Lagos named Neftalí Aravena, a Methodist bishop, as chaplain for the evangelical churches at the Palacio de La Moneda, presenting the act as a fulfilment of the spirit of the Law of Worship of 1999. The Catholic chaplain, Percival Cowley, attended the ceremony. Reports describe it as the first evangelical chaplaincy at the presidential palace, though sources do not settle whether informal ties existed earlier. The post continues, held by evangelical pastors, and was a milestone in the public recognition of Chile's evangelicals.",
      "El primer capellán evangélico de La Moneda",
      "El 13 de diciembre de 2001 el presidente Ricardo Lagos nombró a Neftalí Aravena, obispo metodista, capellán de las iglesias evangélicas en el Palacio de La Moneda, y presentó el acto como cumplimiento del espíritu de la Ley de Cultos de 1999. Asistió a la ceremonia el capellán católico, Percival Cowley. Las crónicas lo describen como la primera capellanía evangélica del palacio presidencial, aunque las fuentes no precisan si existían vínculos informales antes. El cargo continúa, ocupado por pastores evangélicos, y fue un hito en el reconocimiento público de los evangélicos chilenos.",
      [w("Emol, \"Lagos nombró al primer capellán evangélico de La Moneda\"", "https://www.emol.com/noticias/nacional/2001/12/13/73800/lagos-nombro-al-primer-capellan-evangelico-de-la-moneda.html"),
       w("Ministerio del Interior de Chile, on the National Day of Evangelical and Protestant Churches (2025)", "https://interior.gob.cl/noticias/2025/10/30/vicepresidente-elizalde-encabeza-una-nueva-conmemoracion-del-dia-nacional-de-las-iglesias-evangelicas-y-protestantes/")]),
    ev(6, 2018, "Francisco", "Pope Francis in Chile and the Abuse Crisis",
      "Pope Francis visited Chile in January 2018 in the shadow of clerical sexual-abuse scandals. A question about Bishop Juan Barros of Osorno, linked to the abuser Fernando Karadima, led him to say there was no evidence against Barros; he later acknowledged 'grave errors of judgment', sent investigators, and in May 2018 summoned all Chilean bishops to Rome. In June he accepted the resignations of Barros, Gonzalo Duarte and Cristián Caro, and in October he removed two more clerics from the priesthood. The crisis deeply affected the Catholic Church in Chile and its public standing.",
      "El papa Francisco en Chile y la crisis de los abusos",
      "El papa Francisco visitó Chile en enero de 2018 bajo la sombra de los escándalos de abusos sexuales del clero. Una pregunta sobre el obispo de Osorno, Juan Barros, vinculado al abusador Fernando Karadima, lo llevó a decir que no había pruebas contra Barros; luego reconoció 'graves errores de juicio', envió investigadores y en mayo de 2018 convocó a Roma a todos los obispos chilenos. En junio aceptó las renuncias de Barros, Gonzalo Duarte y Cristián Caro, y en octubre separó del sacerdocio a otros dos clérigos. La crisis afectó profundamente a la Iglesia católica en Chile y su presencia pública.",
      [wikies("Viaje apostólico del papa Francisco a Chile", "Viaje_apost%C3%B3lico_del_papa_Francisco_a_Chile"),
       w("Emol, \"Crisis en la Iglesia chilena: Francisco acepta renuncia de obispos Juan Barros y Gonzalo Duarte\" (11 June 2018)", "https://www.emol.com/noticias/Nacional/2018/06/11/909334/Crisis-en-la-iglesia-chilena-Francisco-acepta-renuncia-de-obispos-Juan-Barros-y-Gonzalo-Duarte.html"),
       w("NPR, \"Pope Francis defrocks 2 Chilean priests in deepening sex abuse scandal\" (13 Oct 2018)", "https://www.npr.org/2018/10/13/657125556/pope-francis-defrocks-2-chilean-priests-in-deepening-sex-abuse-scandal")]),
  ],
  "valparaiso": [
    ev(4, 1858, null, "St Paul's Anglican Church on Cerro Concepción",
      "The British community of Valparaíso founded the Anglican church of St Paul on Cerro Concepción in 1858, in Gothic Revival style by the architect William Lloyd. The chaplaincy had existed from 1837, and Memoria Chilena dates the first Anglican church in Chile to 1855 on Cerro Alegre, so St Paul's is not the first Anglican building. It became a National Monument in 1979 and was declared a cathedral of the Anglican Church of Chile on 19 March 2016. The church stands in the port's historic British quarter, a reminder of the foreign merchants who first brought Protestant worship to Chile.",
      "La iglesia anglicana San Pablo en el cerro Concepción",
      "La comunidad británica de Valparaíso fundó en 1858 la iglesia anglicana de San Pablo en el cerro Concepción, de estilo neogótico, obra del arquitecto William Lloyd. La capellanía existía desde 1837, y Memoria Chilena fecha en 1855 la primera iglesia anglicana de Chile, en el cerro Alegre, de modo que San Pablo no es el primer edificio anglicano. Fue declarada Monumento Nacional en 1979 y catedral de la Iglesia Anglicana de Chile el 19 de marzo de 2016. El templo se alza en el histórico barrio británico del puerto, recuerdo de los comerciantes extranjeros que trajeron el culto protestante a Chile.",
      [wiki("St. Paul's Cathedral, Valparaíso", "St._Paul%27s_Cathedral,_Valpara%C3%ADso"),
       w("Memoria Chilena, \"Iglesia anglicana\"", "https://www.memoriachilena.gob.cl/602/w3-article-95447.html"),
       w("Iglesia Anglicana San Pablo de Valparaíso, historical information", "https://saintpauls.github.io/historical-information.html")]),
    ev(5, 1894, null, "The First Seventh-day Adventist Workers in Chile",
      "Two Adventist workers named Davis and Bishop sailed from San Francisco with a few dollars and bags of books and reached the harbour of Valparaíso on 8 December 1894 after 54 days at sea. Selling books, they planted the Adventist work in Chile; by 1896 about a thousand dollars' worth of books had been sold and some thirty people were keeping the Sabbath, according to Ellen G. White. The church opened its first school in Santiago in 1902 and the Púa school in 1906, and became one of the notable Protestant groups in Chile.",
      "Los primeros obreros adventistas en Chile",
      "Dos obreros adventistas, de apellidos Davis y Bishop, zarparon de San Francisco con unos pocos dólares y sacos de libros y llegaron al puerto de Valparaíso el 8 de diciembre de 1894, tras 54 días de travesía. Vendiendo libros, plantaron la obra adventista en Chile; hacia 1896 se habían vendido unos mil dólares en libros y unas treinta personas guardaban el sábado, según Elena G. de White. La iglesia abrió su primera escuela en Santiago en 1902 y la de Púa en 1906, y llegó a ser uno de los grupos protestantes destacados de Chile.",
      [w("Adventist World, \"Moving the work forward in Chile and Ecuador\"", "https://www.adventistworld.org/?p=20114"),
       w("Ellen G. White Estate, writings on the progress of the work in Chile", "https://text.egwwritings.org/amp/read/1140.2898"),
       wiki("Protestantism in Chile")]),
  ],
  "rapa-nui": [
    ev(4, 1864, "Eugène Eyraud", "Eugène Eyraud, the First Missionary on Rapa Nui",
      "Eugène Eyraud, a lay brother of the Congregation of the Sacred Hearts (Picpus Fathers) who had opposed slavery, reached Easter Island in early 1864 and lived alone among the Rapa Nui for about nine to ten months, before being taken back to Chile on 11 October 1864. He returned on 27 March 1866 with Fr Hippolyte Roussel and founded a permanent mission; he died in 1868. The Catholic community marked the 160th anniversary of his arrival in January 2024. His letters are a main source for the island's history after the slave raids that devastated its population.",
      "Eugène Eyraud, primer misionero en Rapa Nui",
      "Eugène Eyraud, hermano lego de la Congregación de los Sagrados Corazones (Padres de Picpus) y opuesto a la esclavitud, llegó a la isla de Pascua a comienzos de 1864 y vivió solo entre los rapanui unos nueve o diez meses, hasta ser llevado de vuelta a Chile el 11 de octubre de 1864. Regresó el 27 de marzo de 1866 con el padre Hippolyte Roussel y fundó una misión permanente; murió en 1868. La comunidad católica conmemoró en enero de 2024 los 160 años de su llegada. Sus cartas son una fuente principal para la historia de la isla tras las redadas de esclavos que devastaron su población.",
      [wiki("Eugène Eyraud", "Eug%C3%A8ne_Eyraud"),
       w("Memoria Chilena, \"Misioneros católicos\"", "https://www.memoriachilena.gob.cl/602/w3-article-96632.html"),
       w("Encyclopaedia Britannica, \"Eugene Eyraud\"", "https://www.britannica.com/biography/Eugene-Eyraud")]),
  ],
  "chiloe": [
    ev(6, 2000, null, "The Wooden Churches of Chiloé",
      "The Jesuits reached Chiloé in 1608 and organised 'circular missions' among the dispersed island population, building chapels that grew into the archipelago's distinctive wooden churches, made entirely of native timber by local boat-carpenters. After the Society was expelled in 1767 the work was continued by Franciscans in the nineteenth century. In December 2000 UNESCO inscribed the Churches of Chiloé as a World Heritage Site for their blend of Spanish Jesuit culture and indigenous skills; some sources note that the list of sixteen churches was completed a year later.",
      "Las iglesias de madera de Chiloé",
      "Los jesuitas llegaron a Chiloé en 1608 y organizaron 'misiones circulares' entre la población dispersa de las islas, y levantaron capillas que se convirtieron en las singulares iglesias de madera del archipiélago, hechas por completo de maderas nativas por carpinteros de ribera locales. Tras la expulsión de la Compañía en 1767, la obra la continuaron los franciscanos en el siglo XIX. En diciembre de 2000 la UNESCO inscribió las Iglesias de Chiloé como Patrimonio de la Humanidad por su mezcla de cultura jesuita española y destreza indígena; algunas fuentes señalan que la lista de dieciséis iglesias se completó un año después.",
      [wiki("Churches of Chiloé", "Churches_of_Chilo%C3%A9"),
       w("Memoria Chilena, \"Iglesias de Chiloé\"", "https://www.memoriachilena.gob.cl/602/w3-article-97384.html"),
       w("Universidad de Chile, \"Las iglesias de Chiloé, Patrimonio de la Humanidad\"", "https://uchile.cl/cultura/chiloe/iglesias/humanidad.html")]),
  ],
  "montevideo": [
    ev(4, 1861, null, "Uruguay Secularises Its Cemeteries",
      "On 18 April 1861 the government of President Bernardo Berro issued a decree on the 'secularisation of cemeteries', taking their administration from the Church. The trigger was the refusal of the parish priest of San José to bury Enrique Jacobsen, a Freemason, in the local cemetery. A second, separate conflict in September of that year involved the bishop and a priest-senator. Historians treat the measure, which some sources call a law, as the start of a longer process by which the Uruguayan state distanced itself from the Church, culminating in the separation of 1917.",
      "Uruguay seculariza sus cementerios",
      "El 18 de abril de 1861 el gobierno del presidente Bernardo Berro dictó un decreto de 'secularización de los cementerios', que quitó a la Iglesia su administración. El detonante fue la negativa del párroco de San José a enterrar en el cementerio local a Enrique Jacobsen, masón. Un segundo conflicto, distinto, en setiembre de ese año involucró al obispo y a un sacerdote senador. Los historiadores consideran la medida, que algunas fuentes llaman ley, el comienzo de un proceso más largo por el cual el Estado uruguayo se distanció de la Iglesia, hasta la separación de 1917.",
      [w("Divulgatio (Universidad Nacional de Quilmes), article on Church–state relations in Uruguay", "https://ojs.unq.edu.ar/index.php/divulgatio/article/download/72/227/539"),
       w("Diálogo Político, \"A cien años de la instauración del Estado laico en el Uruguay\"", "https://dialogopolitico.org/debates/a-cien-anos-de-la-instauracion-del-estado-laico-en-el-uruguay/")]),
    ev(5, 1919, null, "Christmas Becomes Family Day",
      "Law 6,997 of 23 October 1919 secularised the religious holidays of Uruguay. Christmas Day became 'Fiesta de la Familia' (Family Day), the sixth week after Carnival, which coincides with Holy Week, was named 'Semana de Turismo', Epiphany became the Children's Day and 8 December the Day of the Beaches. The change followed earlier measures, such as the removal of crucifixes from hospitals in 1905, divorce in 1907 and secular schooling in 1909, and the Constitution of 1917, in force from 1919, that separated Church and State. Sources differ over how the date of Christmas is treated in practice.",
      "La Navidad pasa a ser Día de la Familia",
      "La Ley 6.997 del 23 de octubre de 1919 secularizó los feriados religiosos de Uruguay. La Navidad pasó a ser 'Fiesta de la Familia', la sexta semana posterior al Carnaval, que coincide con la Semana Santa, se llamó 'Semana de Turismo', la Epifanía fue el Día de los Niños y el 8 de diciembre el Día de las Playas. El cambio siguió a medidas anteriores, como el retiro de crucifijos de los hospitales en 1905, el divorcio en 1907 y la escuela laica en 1909, y a la Constitución de 1917, vigente desde 1919, que separó la Iglesia del Estado. Las fuentes difieren sobre cómo se trata en la práctica la fecha de la Navidad.",
      [w("CNN en Español, \"Uruguay y la Navidad\" (2024)", "https://cnnespanol.cnn.com/2024/12/23/uruguay-navidad-historia-orix"),
       w("El Observador (Uruguay), \"Uruguay y la Navidad: el único país de Latinoamérica que no la reconoce oficialmente\"", "https://www.elobservador.com.uy/free/uruguay-y-la-navidad-el-unico-pais-latinoamerica-que-no-la-reconoce-oficialmente-n5976431"),
       w("Bloomberg Línea, \"Cuál es el único país de Latinoamérica que no celebra la Navidad el 24 de diciembre\"", "https://www.bloomberglinea.com/estilo-de-vida/cual-es-el-unico-pais-de-latinoamerica-que-no-celebra-la-navidad-el-24-de-diciembre/")]),
    ev(6, 1987, null, "The Pope's Cross at Tres Cruces",
      "For the Mass of Pope John Paul II in Montevideo on 1 April 1987, a cross some 24 metres high was raised beside the Tres Cruces bus terminal. President Julio María Sanguinetti proposed that it remain there afterwards, and the proposal split all three parliamentary caucuses in a fierce debate over the secularity of the state. Law 15,870, of June 1987, ordered that the cross be kept permanently at its original site as a memorial of the visit. The cross still stands, and the controversy returned with later religious monuments, such as the statue of the Virgin on the Rambla.",
      "La cruz del Papa en Tres Cruces",
      "Para la misa del papa Juan Pablo II en Montevideo el 1 de abril de 1987 se levantó una cruz de unos 24 metros de altura junto a la terminal de ómnibus de Tres Cruces. El presidente Julio María Sanguinetti propuso que quedara allí después, y la propuesta dividió a las tres bancadas parlamentarias en un duro debate sobre la laicidad del Estado. La Ley 15.870, de junio de 1987, dispuso que la cruz se mantuviera de forma permanente en su emplazamiento original como monumento de la visita. La cruz sigue en pie, y la polémica volvió con monumentos religiosos posteriores, como la estatua de la Virgen en la Rambla.",
      [w("Montevideo Portal, \"La cruz del Papa: el símbolo que dividió al país y sigue en pie\"", "https://www.montevideo.com.uy/Noticias/La-cruz-del-papa-el-simbolo-que-dividio-al-pais-y-sigue-en-pie-39-anos-despues-uc977830"),
       w("Uruguay, Ley N.º 15.870 (22 June 1987), text (Justia)", "https://uruguay.justia.com/nacionales/leyes/ley-15870-jun-22-1987/gdoc"),
       w("Diálogo Político, \"Discutiendo lo sagrado: la laicidad en Uruguay\"", "https://dialogopolitico.org/actualidad/discutiendo-lo-sagrado-la-laicidad-en-uruguay/")]),
  ],
  "nueva-helvecia": [
    ev(4, 1863, null, "The Evangelical Chapel of the Swiss Colony",
      "Nueva Helvecia, the 'Swiss Colony' in the department of Colonia, was settled mainly by German-speaking Swiss, with 25 April 1862 traditionally taken as its founding date after a Basel bank bought land in 1860. In 1863 the colonists built the First Evangelical Chapel, a joint effort of the town's evangelical and Catholic communities, and a second evangelical temple later rose beside it. The congregation's history was written in 1944 by Juan Carlos F. Wirth. It is a reminder that Protestantism in Uruguay arrived with immigrant farming colonies, alongside the Waldensians of nearby Colonia Valdense.",
      "La capilla evangélica de la Colonia Suiza",
      "Nueva Helvecia, la 'Colonia Suiza' del departamento de Colonia, fue poblada sobre todo por suizos de habla alemana, y se toma tradicionalmente el 25 de abril de 1862 como fecha de fundación, después de que un banco de Basilea comprara tierras en 1860. En 1863 los colonos levantaron la Primera Capilla Evangélica, obra conjunta de las comunidades evangélica y católica del pueblo, y junto a ella se alzó luego un segundo templo evangélico. La historia de la congregación fue escrita en 1944 por Juan Carlos F. Wirth. Recuerda que el protestantismo llegó a Uruguay con las colonias agrícolas de inmigrantes, junto a los valdenses de la cercana Colonia Valdense.",
      [wiki("Nueva Helvecia"),
       w("Historical Dictionary of Switzerland, \"Nueva Helvecia\"", "https://hls-dhs-dss.ch/articles/003400"),
       wiki("Swiss Uruguayans")]),
  ],
  "el-ombu": [
    ev(5, 1948, null, "Mennonite Refugees Settle in Uruguay",
      "On 27 October 1948 a first group of about 750 Mennonite refugees, arriving on the ship Volendam, was admitted to Uruguay on condition of living in the countryside and farming; one older list gives 556. About half settled in El Ombú, in Río Negro department, which became the earliest Mennonite colony in the country. A second group of 431 arrived on 19 October 1951 and settled mainly at Gartental. Mennonite congregations were also organised in Montevideo, and by the end of the century more than a thousand Mennonites, immigrants and Spanish-speaking converts, lived in Uruguay.",
      "Refugiados menonitas se asientan en Uruguay",
      "El 27 de octubre de 1948 un primer grupo de unos 750 refugiados menonitas, llegados en el barco Volendam, fue admitido en Uruguay con la condición de vivir en el campo y dedicarse a la agricultura; una lista antigua da 556. Cerca de la mitad se asentó en El Ombú, en el departamento de Río Negro, que fue la primera colonia menonita del país. Un segundo grupo de 431 llegó el 19 de octubre de 1951 y se estableció sobre todo en Gartental. También se organizaron congregaciones menonitas en Montevideo, y a fines del siglo había más de mil menonitas, inmigrantes y conversos hispanohablantes, en Uruguay.",
      [wiki("Mennonites in Uruguay"),
       wiki("El Ombú", "El_Omb%C3%BA"),
       w("El Observador (Uruguay), \"Inmigrantes de la guerra\" (2016)", "https://www.elobservador.com.uy/nota/inmigrantes-de-la-guerra-2016126500")]),
  ],
  "chaco": [
    ev(5, 1930, null, "Fernheim, the Colony of Refugees",
      "In 1930 Mennonites who had fled the collectivisation and persecution of Stalinist Russia, mostly by way of Germany, began to settle the Central Chaco of Paraguay and founded the Fernheim Colony, 'far home'. About 1,700 refugees settled in thirteen villages, and the town of Filadelfia, founded in 1930–31 as the colony's centre, is now the capital of Boquerón department. Fernheim was the second Mennonite colony in Paraguay, after Menno (1927). Debates over identity marked its early decades; Filadelfia remains the colony's administrative centre.",
      "Fernheim, la colonia de los refugiados",
      "En 1930 menonitas que habían huido de la colectivización y la persecución de la Rusia estalinista, la mayoría por Alemania, comenzaron a poblar el Chaco Central de Paraguay y fundaron la Colonia Fernheim, 'hogar lejano'. Unos 1.700 refugiados se asentaron en trece aldeas, y la ciudad de Filadelfia, fundada en 1930–31 como centro de la colonia, es hoy la capital del departamento de Boquerón. Fernheim fue la segunda colonia menonita del Paraguay, después de Menno (1927). Los debates sobre la identidad marcaron sus primeras décadas; Filadelfia sigue siendo el centro administrativo de la colonia.",
      [wiki("Fernheim Colony"),
       wiki("Mennonites in Paraguay"),
       w("Mennonite Quarterly Review (Goshen College), Reimer, October 2002, on Fernheim", "https://www.goshen.edu/mqr/?p=5419")]),
    ev(5, 1947, null, "Neuland, Home for Mennonite Refugees after the War",
      "After the Second World War thousands of Plautdietsch-speaking Mennonites from the Soviet Union were left displaced in Europe. In 1947 the Mennonite Central Committee bought land in Boquerón department, Paraguay, and the Neuland Colony was founded on 26 April 1947; reports give 2,474 settlers. The ship Volendam carried some 2,300 refugees that year, and others founded Volendam Colony in eastern Paraguay. Neuland, now part of the municipality of Mariscal Estigarribia, has about 5,000 inhabitants and has struggled with scarce drinking water, a continuing challenge of Chaco settlement.",
      "Neuland, hogar de refugiados menonitas tras la guerra",
      "Tras la Segunda Guerra Mundial miles de menonitas de habla plautdietsch de la Unión Soviética quedaron desplazados en Europa. En 1947 el Comité Central Menonita compró tierras en el departamento de Boquerón, Paraguay, y la Colonia Neuland se fundó el 26 de abril de 1947; se citan 2.474 colonos. El barco Volendam llevó ese año a unos 2.300 refugiados, y otros fundaron la Colonia Volendam en el Paraguay oriental. Neuland, hoy parte del municipio de Mariscal Estigarribia, tiene unos 5.000 habitantes y ha luchado con la escasez de agua potable, un desafío constante del asentamiento en el Chaco.",
      [wiki("Neuland Colony"),
       w("La Nación (Paraguay), \"Neuland, progresiva colonia del Chaco\"", "https://lanacion.com.py/2016/10/16/neuland-progresiva-colonia-del-chaco"),
       w("Anabaptist World, on the Mennonite refugees' voyage to Paraguay in 1947", "https://anabaptistworld.org/jesus-go-us/")]),
  ],
  "friesland": [
    ev(5, 1937, null, "Friesland, the First Mennonite Colony in Eastern Paraguay",
      "In July 1937 about a third of the people of Fernheim left the Chaco in search of better opportunities and founded Friesland Colony in San Pedro department, some 45 kilometres east of the Paraguay River; it was the first Mennonite colony founded in the country's Eastern Region. A decade later its settlers helped receive the refugees who founded Volendam Colony. Friesland shows the move of part of the Paraguayan Mennonite community from the Chaco to the east of the country.",
      "Friesland, primera colonia menonita del Paraguay oriental",
      "En julio de 1937 cerca de un tercio de los habitantes de Fernheim dejó el Chaco en busca de mejores oportunidades y fundó la Colonia Friesland en el departamento de San Pedro, a unos 45 kilómetros al este del río Paraguay; fue la primera colonia menonita fundada en la Región Oriental del país. Diez años después sus colonos ayudaron a recibir a los refugiados que fundaron la Colonia Volendam. Friesland muestra el paso de parte de la comunidad menonita paraguaya del Chaco al este del país.",
      [w("ABC Color, \"Friesland y el triunfo de la voluntad\" (2022)", "https://www.abc.com.py/opinion/2022/10/18/friesland-y-el-triunfo-de-la-voluntad/"),
       w("Colonia Friesland, \"The History of the Mennonites\"", "https://friesland.com.py/en/?p=47"),
       wiki("Mennonites in Paraguay")]),
  ],
  "yalve-sanga": [
    ev(5, 1946, "Sepe Lhama", "The First Enlhet Baptisms at Yalve Sanga",
      "Mennonite missionaries established a post at Yalve Sanga in the Paraguayan Chaco in the mid-1930s, with a first school in 1937; sources date the founding of the mission between 1935 and 1936. On 26 February 1946 Sepe Lhama, the first Enlhet (Lengua) person to embrace Christianity, was baptised together with six others, who became the first to settle in a community and leave nomadic life. The mission's cooperation work was formalised in 1970 as ASCIM (Asociación de Servicios de Cooperación Indígena-Menonita), whose headquarters are at Yalve Sanga, and the Enlhet Mennonite churches now have their own leadership.",
      "Los primeros bautismos enlhet en Yalve Sanga",
      "Misioneros menonitas establecieron un puesto en Yalve Sanga, en el Chaco paraguayo, a mediados de la década de 1930, con una primera escuela en 1937; las fuentes fechan la fundación de la misión entre 1935 y 1936. El 26 de febrero de 1946 fue bautizado Sepe Lhama, el primer enlhet (lengua) que abrazó el cristianismo, junto con otros seis, que fueron los primeros en asentarse en una comunidad y dejar la vida nómada. La obra de cooperación de la misión se formalizó en 1970 como ASCIM (Asociación de Servicios de Cooperación Indígena-Menonita), cuya sede está en Yalve Sanga, y las iglesias menonitas enlhet tienen hoy su propio liderazgo.",
      [w("Universidad Evangélica del Paraguay, Teófilo (journal), article on the Enlhet community of Yalve Sanga", "https://ojs.uep.edu.py/index.php/Teofilo/article/download/300/231"),
       w("ASCIM, \"Asociación de Servicios de Cooperación Indígena-Menonita\"", "https://ascim.org/index.php/en/amh/item/870"),
       w("Mennonite Heritage Archives, \"A church built for and with Enlhet people\"", "https://archives.mhsc.ca/mennonites-missions-paraguay-chaco-boreal")]),
  ],
  "asuncion": [
    ev(6, 1969, "Ismael Rolón", "The Church and Stroessner Clash After Cristo Rey",
      "In November 1969 protests against the visit of Nelson Rockefeller to Paraguay ended with a police intervention at the Jesuit church of Cristo Rey in Asunción, where persecuted people had taken shelter. Stroessner's government shut the Jesuit premises and expelled Fr Francisco de Paula Oliva; the bishops protested, and Bishop Ismael Rolón of Caacupé suspended the Virgin of Caacupé procession in protest. Archbishop Aníbal Mena Porta resigned at the end of 1969, and an agreement with the government led to Rolón's appointment as Archbishop of Asunción in 1970. The conflict made the Church a leading voice of criticism of the regime.",
      "La Iglesia y Stroessner chocan tras Cristo Rey",
      "En noviembre de 1969 las protestas por la visita de Nelson Rockefeller a Paraguay terminaron con una intervención policial en la iglesia jesuita de Cristo Rey, en Asunción, donde se habían refugiado perseguidos. El gobierno de Stroessner clausuró la sede jesuita y expulsó al padre Francisco de Paula Oliva; los obispos protestaron, y el obispo Ismael Rolón, de Caacupé, suspendió en señal de protesta la procesión de la Virgen de Caacupé. El arzobispo Aníbal Mena Porta renunció a fines de 1969 y un acuerdo con el gobierno llevó al nombramiento de Rolón como arzobispo de Asunción en 1970. El conflicto convirtió a la Iglesia en una de las principales voces críticas del régimen.",
      [w("ABC Color, \"Rockefeller, Stroessner y la suspendida procesión de Caacupé\"", "https://www.abc.com.py/edicion-impresa/suplementos/abc-revista/2023/12/03/rockefeller-stroessner-y-la-suspendida-procesion-de-caacupe/"),
       w("Última Hora, \"El día que Stroessner se quedó sin procesión\"", "https://www.ultimahora.com/el-dia-que-stroessner-se-quedo-sin-procesion"),
       w("Library of Congress Country Studies, Paraguay: the Roman Catholic Church", "https://countrystudies.us/paraguay/58.htm")]),
    ev(6, 1976, null, "The Churches Committee for Emergency Aid",
      "On 28 June 1976, in response to mass arrests under the Stroessner dictatorship, the Comité de Iglesias para Ayudas de Emergencia (CIPAE) was formed as an ecumenical body by the Disciples of Christ, the Evangelical Church of the River Plate and the Catholic Church, under the protection of Archbishop Ismael Rolón. It defended prisoners and the persecuted. The Inter-American Commission on Human Rights recorded in 1978 that José Carlos Rodríguez, a member of its executive, was detained with colleagues. CIPAE continued after the fall of the regime, supporting victims and cooperating with the Ministry of Justice in cases of the disappeared.",
      "El Comité de Iglesias para Ayudas de Emergencia",
      "El 28 de junio de 1976, en respuesta a detenciones masivas bajo la dictadura de Stroessner, se formó el Comité de Iglesias para Ayudas de Emergencia (CIPAE) como organismo ecuménico de la Iglesia Cristiana Discípulos de Cristo, la Iglesia Evangélica del Río de la Plata y la Iglesia católica, bajo la protección del arzobispo Ismael Rolón. Defendió a presos y perseguidos. La Comisión Interamericana de Derechos Humanos registró en 1978 que José Carlos Rodríguez, miembro de su ejecutiva, fue detenido junto con colaboradores. El CIPAE siguió tras la caída del régimen, apoyando a víctimas y cooperando con el Ministerio de Justicia en casos de desaparecidos.",
      [w("Global Ministries (Disciples of Christ and UCC), \"Churches Committee for Emergency Aid (CIPAE), Paraguay\"", "https://globalministries.org/?p=20499"),
       w("Presbyterian Historical Society, \"Snapshot from Paraguay\"", "https://history.pcusa.org/node/10284"),
       w("Inter-American Commission on Human Rights, Report on the situation of human rights in Paraguay (1978), chapter 7", "https://cidh.oas.org/countryrep/Paraguay78eng/chap.7.htm")]),
    ev(6, 2008, "Fernando Lugo", "A Bishop Is Elected President",
      "Fernando Lugo, Catholic bishop of San Pedro, asked in December 2006 to leave the clerical state in order to run for president, and was suspended 'a divinis'. In April 2008 he won the election, ending six decades of Colorado Party rule, and took office on 15 August 2008. In July 2008 the Holy See granted the reduction of the president-elect to the lay state, stating that the office was incompatible with episcopal ministry. The case showed both the Church's weight in Paraguayan public life and the limits canon law placed on political office for clergy.",
      "Un obispo es elegido presidente",
      "Fernando Lugo, obispo católico de San Pedro, pidió en diciembre de 2006 dejar el estado clerical para postularse a la presidencia y fue suspendido 'a divinis'. En abril de 2008 ganó las elecciones, poniendo fin a seis décadas de dominio del Partido Colorado, y asumió el 15 de agosto de 2008. En julio de 2008 la Santa Sede concedió la reducción al estado laical del presidente electo, y declaró que el cargo era incompatible con el ministerio episcopal. El caso mostró a la vez el peso de la Iglesia en la vida pública paraguaya y los límites que el derecho canónico pone a los clérigos para ocupar cargos políticos.",
      [wiki("Fernando Lugo"),
       w("ACI Prensa, \"Santa Sede anuncia pérdida del estado clerical de ex obispo Lugo\"", "https://www.aciprensa.com/noticias/26916/santa-sede-anuncia-perdida-del-estado-clerical-de-ex-obispo-lugo"),
       w("Cooperativa (Chile), \"Vaticano aceptó que el presidente electo de Paraguay deje de ser sacerdote\" (30 July 2008)", "https://cooperativa.cl/noticias/mundo/paraguay/politica/vaticano-acepto-que-el-presidente-electo-de-paraguay-deje-de-ser-sacerd/2008-07-30/102155.html")]),
  ],
};

